// Replays every vector generated by the Swift engine (ShengjiCore ShengjiVectors target) through
// the TypeScript engine. Every value must match exactly, learner-facing text included. Entries for
// tables of 6 and 8 players (3 and 4 decks) follow the classic ones in each list; they carry a
// `players` (or `decks`) field, and an entry without one is a 4-player, 2-deck case.
// Regenerate with: cd ShengjiCore && swift run ShengjiVectors ../server/test/vectors

import assert from "node:assert/strict";
import { test } from "node:test";
import { isDeepStrictEqual } from "node:util";
import * as E from "../src/engine/index.ts";
import type { Card, Declaration, Rank, Round, RoundError, RoundResult, Suit, SuitGroup, Trump } from "../src/engine/index.ts";
import { loadVectors, parity } from "./support.ts";

// MARK: Vector file shapes

interface CombosFile {
  suits: { suit: Suit; symbol: string; name: string; singularName: string; isRed: boolean }[];
  ranks: { rank: Rank; label: string; name: string; points: number; advanced: Rank[][] }[];
  faces: {
    face: number;
    suit: Suit | null;
    rank: Rank | null;
    isJoker: boolean;
    points: number;
    description: string;
    longName: string;
  }[];
  groups: { group: SuitGroup; name: string; symbol: string }[];
  shapes: { shape: E.ComboShape; name: string; cardCount: number; pairCount: number }[];
  trumps: {
    trump: Trump;
    description: string;
    summary: string;
    plainSuitOrder: Suit[];
    isTrump: boolean[];
    group: SuitGroup[];
    strength: number[];
    sortKey: number[];
    highToLow: number[];
    sortedDeck: Card[];
  }[];
  cases: {
    trump: Trump;
    cards: Card[];
    group: SuitGroup | null;
    sorted: Card[];
    decompose: E.Component[];
    shape: E.ComboShape | null;
    isPair: boolean;
    pairs: Card[][];
    pairCount: number;
    longestRun: number;
    singles: Card[];
    tractors: { length: number; cards: Card[][]; tops: number[] }[];
    isThrow: boolean;
    kittyMultiplier: number;
  }[];
  /** Card sets from 3 or 4 decks. */
  setCases: {
    decks: number;
    trump: Trump;
    cards: Card[];
    group: SuitGroup | null;
    sorted: Card[];
    maxCopies: number;
    decompose: E.Component[];
    shape: E.ComboShape | null;
    pairs: Card[][];
    pairCount: number;
    longestRun: number;
    tractors: Card[][][];
    widths: {
      width: number;
      sets: Card[][];
      longestRun: number;
      tractors: { length: number; cards: Card[][]; tops: number[] }[];
    }[];
    units: Card[][][];
    isThrow: boolean;
    kittyMultiplier: number;
  }[];
}

/** A follow requirement as the vectors write it: `units` only when they say more than the rest. */
type RequirementJSON = { tractorLengths: number[]; totalPairs: number; units?: E.ComboShape[] };

function requirementJSON(requirement: E.FollowRequirement): RequirementJSON {
  const out: RequirementJSON = { tractorLengths: requirement.tractorLengths, totalPairs: requirement.totalPairs };
  const classic = E.classicRequirement(requirement.tractorLengths, requirement.totalPairs).units;
  if (!E.isClassicRequirement(requirement) || !isDeepStrictEqual(requirement.units, classic)) out.units = requirement.units;
  return out;
}

/** The table of a vector entry (no `players` field: the classic 4 players). */
function tableOf(entry: { players?: number }): E.TableSize {
  return E.tableSize(entry.players ?? 4);
}

interface RulesFile {
  positions: {
    players?: number;
    trump: Trump;
    leader: number;
    hands: Card[][];
    leads: {
      cards: Card[];
      violation: E.LeadViolation | null;
      explanation: string | null;
      isThrow: boolean;
      check: unknown;
      pool: Card[];
      poolCheck: unknown;
    }[];
    lead: Card[];
    follows: {
      seat: number;
      requirement: RequirementJSON;
      plays: { cards: Card[]; matches: boolean; violation?: E.FollowViolation; explanation?: string }[];
    }[];
    tricks: { plays: E.Play[]; winners: number[] }[];
  }[];
}

type RoundAction =
  | { op: "deal"; count: number }
  | { op: "dealAll" }
  | ({ op: "check" } & Record<string, unknown>)
  | { op: "finishDealing"; phase: string; dealer: number | null; trump: Trump; trumpFromKitty: Card | null }
  | {
      op: "declare";
      available: Declaration[][];
      declaration: Declaration;
      description: string;
      error: RoundError | null;
      explanation: string | null;
    }
  | { op: "bury"; cards: Card[]; error: RoundError | null; explanation: string | null }
  | {
      op: "play";
      player: number;
      cards: Card[];
      outcome?: E.PlayOutcome;
      trick?: { winner: number; points: number };
      error?: RoundError;
      explanation?: string;
    };

interface RoundsFile {
  rounds: {
    players?: number;
    seed: number;
    trumpRank: Rank;
    dealer: number | null;
    deck: Card[];
    actions: RoundAction[];
    result: RoundResult;
  }[];
}

interface GamesFile {
  outcomes: { decks?: number; points: number; outcome: E.LevelOutcome }[];
  games: {
    players?: number;
    settings: E.GameSettings;
    steps: {
      nextTrumpRank: Rank;
      nextDealer: number | null;
      result: RoundResult;
      summary: Omit<E.RoundSummary, "result">;
      state: { levels: Rank[]; nextDealer: number | null; roundsPlayed: number; winner: number | null; nextTrumpRank: Rank };
    }[];
  }[];
}

interface ViewsFile {
  cases: {
    label: string;
    players: E.SeatPlayer[];
    game: E.GameState;
    round: Round;
    /** The Swift `SeatView` Codable JSON for every seat (absent optionals left out). */
    views: unknown[];
  }[];
}

const combos = loadVectors<CombosFile>("combos.json");
const rules = loadVectors<RulesFile>("rules.json");
const rounds = loadVectors<RoundsFile>("rounds.json");
const games = loadVectors<GamesFile>("games.json");
const edges = loadVectors<EdgesFile>("edges.json");
const views = loadVectors<ViewsFile>("views.json");

interface EdgesFile {
  declarations: { players?: number; declaration: Declaration; description: string }[];
  kittyFlips: {
    players?: number;
    trumpRank: Rank;
    dealer: number | null;
    kitty: Card[];
    phase: string;
    trump: Trump;
    trumpFromKitty: Card | null;
    dealerAfter: number | null;
    leader: number;
  }[];
  throws: {
    players?: number;
    trump: Trump;
    leader: number;
    hands: Card[][];
    cards: Card[];
    isThrow: boolean;
    check: unknown;
    pool: Card[];
    poolCheck: unknown;
  }[];
  follows: {
    decks?: number;
    trump: Trump;
    lead: Card[];
    hand: Card[];
    requirement: RequirementJSON;
    plays: { cards: Card[]; matches: boolean; violation?: E.FollowViolation; explanation?: string }[];
  }[];
  tricks: { players?: number; trump: Trump; plays: E.Play[]; winners: number[] }[];
}

// MARK: combos.json

test("vectors: suits, ranks, faces, groups and shapes", () => {
  const p = parity("tables");
  for (const s of combos.suits) {
    p.equal(`suit ${s.suit}`, {
      suit: s.suit,
      symbol: E.suitSymbol(s.suit),
      name: E.suitName(s.suit),
      singularName: E.suitSingularName(s.suit),
      isRed: E.isRedSuit(s.suit),
    }, s);
  }
  for (const r of combos.ranks) {
    const advanced = [-1, 0, 1, 2, 3, 4, 5].map((steps) => E.ALL_RANKS.map((cap) => E.advanceRank(r.rank, steps, cap)));
    p.equal(`rank ${r.rank}`, {
      rank: r.rank,
      label: E.rankLabel(r.rank),
      name: E.rankName(r.rank),
      points: E.rankPoints(r.rank),
      advanced,
    }, r);
  }
  for (const f of combos.faces) {
    for (const card of [f.face, f.face + 54]) {
      p.equal(`card ${card}`, {
        face: E.faceOf(card),
        suit: E.suitOf(card),
        rank: E.rankOf(card),
        isJoker: E.isJoker(card),
        points: E.cardPoints(card),
        description: E.cardDescription(card),
        longName: E.cardLongName(card),
      }, f);
    }
  }
  for (const g of combos.groups) {
    p.equal(`group ${g.group}`, { group: g.group, name: E.groupName(g.group), symbol: E.groupSymbol(g.group) }, g);
  }
  for (const s of combos.shapes) {
    p.equal(`shape ${JSON.stringify(s.shape)}`, {
      shape: s.shape,
      name: E.shapeName(s.shape),
      cardCount: E.shapeCardCount(s.shape),
      pairCount: E.shapePairCount(s.shape),
    }, s);
  }
  assert.ok(p.count() > 130);
  assert.ok(combos.shapes.some((s) => s.shape.type === "setTractor"), "no tractor-of-sets shapes");
  p.finish();
});

test("vectors: trump order for every trump context", () => {
  const p = parity("trumps");
  const faces = Array.from({ length: 54 }, (_, i) => i);
  for (const t of combos.trumps) {
    const trump = t.trump;
    p.equal(`trump ${JSON.stringify(trump)}`, {
      trump,
      description: E.trumpDescription(trump),
      summary: E.trumpSummary(trump),
      plainSuitOrder: E.plainSuitOrder(trump),
      isTrump: faces.map((f) => E.isTrump(trump, f)),
      group: faces.map((f) => E.groupOf(trump, f)),
      strength: faces.map((f) => E.strength(trump, f)),
      sortKey: faces.map((f) => E.sortKey(trump, f)),
      highToLow: E.trumpFacesHighToLow(trump),
      sortedDeck: E.sortCards(trump, E.doubleDeck()),
    }, t);
    // Every copy of a face (up to four decks) behaves identically.
    for (const f of faces) {
      for (const copy of [1, 2, 3]) {
        const card = f + 54 * copy;
        p.equal(`copy ${copy} of face ${f} under ${JSON.stringify(trump)}`,
          [E.strength(trump, card), E.groupOf(trump, card), E.sortKey(trump, card)],
          [t.strength[f], t.group[f], t.sortKey[f]]);
      }
    }
  }
  assert.equal(combos.trumps.length, 65);
  p.finish();
});

test("vectors: decomposition, shapes, pairs and tractors of card sets", () => {
  const p = parity("combos");
  for (const [index, c] of combos.cases.entries()) {
    const { trump, cards } = c;
    const longest = E.longestRun(cards, trump);
    const actual = {
      trump,
      cards,
      group: E.groupOfCards(cards, trump),
      sorted: E.sortCards(trump, cards),
      decompose: E.decompose(cards, trump),
      shape: E.shapeOf(cards, trump),
      isPair: E.isPair(cards),
      pairs: E.pairsIn(cards, trump),
      pairCount: E.pairCount(cards),
      longestRun: longest,
      singles: E.componentsOf(E.SINGLE, cards, trump).map((component) => component.cards[0]),
      tractors: c.tractors.map(({ length }) => {
        const components = E.componentsOf(E.tractorShape(length), cards, trump);
        return { length, cards: components.map((x) => x.cards), tops: components.map((x) => x.topStrength) };
      }),
      isThrow: E.isThrow(cards, trump),
      kittyMultiplier: E.kittyMultiplier(cards, trump),
    };
    p.equal(`combos case ${index} ${E.shortText(cards)} (trump ${E.trumpDescription(trump)})`, actual, c);
    // The plain tractor search agrees with componentsOf.
    for (const t of c.tractors) {
      p.equal(`combos case ${index} tractorsIn length ${t.length}`, E.tractorsIn(cards, t.length, trump), t.cards);
    }
    // componentsOf(pair) is pairsIn with components.
    p.equal(`combos case ${index} componentsOf pair`, E.componentsOf(E.PAIR, cards, trump).map((x) => x.cards), c.pairs);
  }
  assert.ok(combos.cases.length >= 1000);
  p.finish();
});

test("vectors: triples, four of a kind and tractors of them from three and four decks", () => {
  const p = parity("setCombos");
  const unitShapes: E.ComboShape[] = [
    E.SINGLE,
    E.PAIR,
    E.tractorShape(2),
    E.setShape(3),
    E.setShape(4),
    E.setTractorShape(3, 2),
    E.setTractorShape(4, 2),
  ];
  const seen = { setShapes: 0, setTractors: 0, quads: 0 };
  for (const [index, c] of combos.setCases.entries()) {
    const { trump, cards } = c;
    const decomposition = E.decompose(cards, trump);
    for (const component of decomposition) {
      if (component.shape.type === "set") seen.setShapes++;
      if (component.shape.type === "setTractor") seen.setTractors++;
      if (E.shapeWidth(component.shape) === 4) seen.quads++;
    }
    const longest = E.longestRun(cards, trump);
    const actual = {
      decks: c.decks,
      trump,
      cards,
      group: E.groupOfCards(cards, trump),
      sorted: E.sortCards(trump, cards),
      maxCopies: E.maxCopies(cards),
      decompose: decomposition,
      shape: E.shapeOf(cards, trump),
      pairs: E.pairsIn(cards, trump),
      pairCount: E.pairCount(cards),
      longestRun: longest,
      tractors: c.tractors.map((_, i) => E.tractorsIn(cards, i + 2, trump)),
      widths: c.widths.map(({ width, tractors }) => ({
        width,
        sets: E.setsIn(cards, width, trump),
        longestRun: E.longestSetRun(cards, width, trump),
        tractors: tractors.map(({ length }) => {
          const components = E.componentsOf(E.setTractorShape(width, length), cards, trump);
          return { length, cards: components.map((x) => x.cards), tops: components.map((x) => x.topStrength) };
        }),
      })),
      units: unitShapes.map((shape) => E.unitsOf(shape, cards, trump)),
      isThrow: E.isThrow(cards, trump),
      kittyMultiplier: E.kittyMultiplier(cards, trump),
    };
    p.equal(`set case ${index} ${E.shortText(cards)} (${c.decks} decks, trump ${E.trumpDescription(trump)})`, actual, c);
  }
  assert.ok(combos.setCases.length >= 300);
  assert.ok(seen.setShapes >= 300 && seen.setTractors >= 50 && seen.quads >= 50, JSON.stringify(seen));
  p.finish();
});

// MARK: rules.json

test("vectors: leads, throws, follows and trick winners", () => {
  const p = parity("rules");
  let followCases = 0;
  const big = { positions: 0, setViolations: 0, setTractorViolations: 0, unitRequirements: 0 };
  for (const [index, pos] of rules.positions.entries()) {
    const { trump, leader, hands } = pos;
    if (pos.players !== undefined) {
      big.positions++;
      assert.equal(hands.length, pos.players);
    }
    const where = `position ${index} (${pos.players ?? 4} players, trump ${E.trumpDescription(trump)}, leader ${leader})`;
    for (const lead of pos.leads) {
      const violation = E.validateLead(lead.cards, hands[leader], trump);
      p.equal(`${where} lead ${E.shortText(lead.cards)}`, {
        cards: lead.cards,
        violation,
        explanation: violation === null ? null : E.leadViolationExplanation(violation),
        isThrow: E.isThrow(lead.cards, trump),
        check: E.checkThrow(lead.cards, leader, hands, trump),
        pool: lead.pool,
        poolCheck: E.checkThrowAgainstPool(lead.cards, lead.pool, trump),
      }, lead);
    }
    const ledGroup = E.groupOfCards(pos.lead, trump) ?? E.groupOf(trump, pos.lead[0]);
    for (const follow of pos.follows) {
      const hand = hands[follow.seat];
      p.equal(`${where} requirement for seat ${follow.seat} to ${E.shortText(pos.lead)}`,
        requirementJSON(E.followRequirement(pos.lead, E.cardsInGroup(hand, ledGroup, trump), trump)), follow.requirement);
      if (follow.requirement.units !== undefined) big.unitRequirements++;
      for (const play of follow.plays) {
        followCases++;
        const violation = E.validateFollow(play.cards, hand, pos.lead, trump);
        if (violation?.case === "mustPlaySets") big.setViolations++;
        if (violation?.case === "mustPlaySetTractor") big.setTractorViolations++;
        const actual: Record<string, unknown> = {
          cards: play.cards,
          matches: E.matchesStructure(play.cards, pos.lead, trump),
        };
        if (violation !== null) {
          actual.violation = violation;
          actual.explanation = E.followViolationExplanation(violation);
        }
        p.equal(`${where} seat ${follow.seat} plays ${E.shortText(play.cards)} to ${E.shortText(pos.lead)}`, actual, play);
      }
    }
    for (const trick of pos.tricks) {
      const winners = trick.plays.map((_, k) => E.winningIndex(trick.plays.slice(0, k + 1), trump));
      p.equal(`${where} trick ${trick.plays.map((x) => E.shortText(x.cards)).join(" | ")}`, winners, trick.winners);
    }
  }
  assert.ok(followCases > 10000, `only ${followCases} follow cases`);
  assert.ok(big.positions >= 150 && big.unitRequirements >= 100 && big.setViolations >= 200 && big.setTractorViolations >= 10,
    JSON.stringify(big));
  p.finish();
});

// MARK: rounds.json

function snapshot(round: Round): Record<string, unknown> {
  return {
    op: "check",
    phase: round.phase,
    dealer: round.dealer,
    leader: round.leader,
    turn: E.turn(round),
    declarerTeam: E.declarerTeam(round),
    trump: round.trump,
    trumpFromKitty: round.trumpFromKitty,
    declaration: round.declaration,
    declarationCount: round.declarationHistory.length,
    hands: round.hands,
    kitty: round.kitty,
    undealtCount: round.undealt.length,
    nextToReceive: round.nextToReceive,
    trickCount: round.tricks.length,
    defenderTrickPoints: round.defenderTrickPoints,
    playedCount: E.playedCards(round).length,
  };
}

function errorFields(error: RoundError | null): { error: RoundError | null; explanation: string | null } {
  return { error, explanation: error === null ? null : E.roundErrorExplanation(error) };
}

test("vectors: whole rounds through the Round API (state round-tripped through JSON)", () => {
  const p = parity("rounds");
  let actions = 0;
  const big = { rounds: 0, bigDeclarations: 0 };
  for (const v of rounds.rounds) {
    const table = tableOf(v);
    if (v.players !== undefined) big.rounds++;
    let round = E.newRound(v.trumpRank, v.dealer, v.deck, table);
    let ok = true;
    for (const [index, a] of v.actions.entries()) {
      if (!ok) break;
      actions++;
      const where = `round seed ${v.seed}, action ${index} (${a.op})`;
      switch (a.op) {
        case "deal":
          for (let k = 0; k < a.count; k++) E.dealNext(round);
          break;
        case "dealAll":
          E.dealAll(round);
          break;
        case "check":
          ok = p.equal(where, snapshot(round), a);
          break;
        case "finishDealing":
          E.finishDealing(round);
          ok = p.equal(where, {
            op: a.op,
            phase: round.phase,
            dealer: round.dealer,
            trump: round.trump,
            trumpFromKitty: round.trumpFromKitty,
          }, a);
          break;
        case "declare": {
          const available = E.allSeats(table.players).map((seat) => E.availableDeclarations(round, seat));
          const description = E.declarationDescription(a.declaration, 0, table.players);
          const error = E.declare(round, a.declaration);
          if (error === null && a.declaration.strength >= 5) big.bigDeclarations++;
          ok = p.equal(`${where} ${description}`, {
            op: a.op,
            available,
            declaration: a.declaration,
            description,
            ...errorFields(error),
          }, a);
          break;
        }
        case "bury": {
          const error = E.bury(round, a.cards);
          ok = p.equal(`${where} ${E.shortText(a.cards)}`, { op: a.op, cards: a.cards, ...errorFields(error) }, a);
          break;
        }
        case "play": {
          const tricksBefore = round.tricks.length;
          const result = E.play(round, a.cards, a.player);
          const actual: Record<string, unknown> = { op: a.op, player: a.player, cards: a.cards };
          if (result.ok) {
            if (result.outcome.type !== "played") actual.outcome = result.outcome;
            if (round.tricks.length > tricksBefore) {
              const trick = round.tricks[round.tricks.length - 1];
              actual.trick = { winner: trick.winner, points: trick.points };
            }
          } else {
            Object.assign(actual, errorFields(result.error));
          }
          ok = p.equal(`${where} seat ${a.player} plays ${E.shortText(a.cards)}`, actual, a);
          break;
        }
      }
      // The state is stored as JSON between actions (Durable Object storage): it must survive that.
      const stored = JSON.parse(JSON.stringify(round)) as Round;
      if (ok) ok = p.equal(`${where}: JSON round trip`, stored, round);
      round = stored;
    }
    if (ok) p.equal(`round seed ${v.seed} result`, round.result, v.result);
  }
  assert.ok(rounds.rounds.length >= 150);
  assert.ok(actions > 15000, `only ${actions} actions`);
  assert.ok(big.rounds >= 30 && big.bigDeclarations >= 10, JSON.stringify(big));
  p.finish();
});

// MARK: edges.json

test("vectors: declaration text for every strength, suit and card variant", () => {
  const p = parity("declarations");
  for (const d of edges.declarations) {
    p.equal(`declaration ${JSON.stringify(d.declaration)} (${d.players ?? 4} players)`,
      E.declarationDescription(d.declaration, 0, d.players ?? 4), d.description);
  }
  assert.ok(edges.declarations.length >= 150);
  assert.ok(edges.declarations.filter((d) => d.declaration.strength >= 8 && d.players !== undefined).length >= 50);
  p.finish();
});

test("vectors: kitty flips (trump-rank card, joker, highest card with ties)", () => {
  const p = parity("kittyFlips");
  for (const [index, f] of edges.kittyFlips.entries()) {
    const table = tableOf(f);
    const rest = E.deckCards(table.decks).filter((card) => !f.kitty.includes(card));
    const round = E.newRound(f.trumpRank, f.dealer, [...rest, ...f.kitty], table);
    E.dealAll(round);
    E.finishDealing(round);
    const players: { players?: number } = f.players === undefined ? {} : { players: f.players };
    p.equal(`kitty flip ${index}: ${E.shortText(f.kitty)} (rank ${E.rankLabel(f.trumpRank)}, dealer ${f.dealer})`, {
      ...players,
      trumpRank: f.trumpRank,
      dealer: f.dealer,
      kitty: f.kitty,
      phase: round.phase,
      trump: round.trump,
      trumpFromKitty: round.trumpFromKitty,
      dealerAfter: round.dealer,
      leader: round.leader,
    }, f);
    p.equal(`kitty flip ${index}: kittyFlip`, E.kittyFlip(f.kitty, f.trumpRank), { suit: f.trump.suit, card: f.trumpFromKitty });
  }
  assert.ok(edges.kittyFlips.length >= 100);
  p.finish();
});

test("vectors: throws with tied components, odd leader seats and short hand lists", () => {
  const p = parity("throws");
  let failures = 0;
  for (const [index, t] of edges.throws.entries()) {
    const check = E.checkThrow(t.cards, t.leader, t.hands, t.trump);
    if (check.type === "fails") failures++;
    const players: { players?: number } = t.players === undefined ? {} : { players: t.players };
    p.equal(`throw ${index} ${E.shortText(t.cards)} by ${t.leader} (trump ${E.trumpDescription(t.trump)})`, {
      ...players,
      trump: t.trump,
      leader: t.leader,
      hands: t.hands,
      cards: t.cards,
      isThrow: E.isThrow(t.cards, t.trump),
      check,
      pool: t.pool,
      poolCheck: E.checkThrowAgainstPool(t.cards, t.pool, t.trump),
    }, t);
  }
  assert.ok(failures >= 100, `only ${failures} failing throws`);
  p.finish();
});

test("vectors: follows to leads of several tractors", () => {
  const p = parity("follows");
  let tractorViolations = 0;
  let setViolations = 0;
  for (const [index, f] of edges.follows.entries()) {
    const ledGroup = E.groupOfCards(f.lead, f.trump) ?? E.groupOf(f.trump, f.lead[0]);
    const where = `follow ${index} to ${E.shortText(f.lead)} (trump ${E.trumpDescription(f.trump)})`;
    p.equal(`${where}: requirement`,
      requirementJSON(E.followRequirement(f.lead, E.cardsInGroup(f.hand, ledGroup, f.trump), f.trump)), f.requirement);
    for (const play of f.plays) {
      const violation = E.validateFollow(play.cards, f.hand, f.lead, f.trump);
      if (violation?.case === "mustPlayTractor") tractorViolations++;
      if (violation?.case === "mustPlaySets" || violation?.case === "mustPlaySetTractor") setViolations++;
      const actual: Record<string, unknown> = { cards: play.cards, matches: E.matchesStructure(play.cards, f.lead, f.trump) };
      if (violation !== null) {
        actual.violation = violation;
        actual.explanation = E.followViolationExplanation(violation);
      }
      p.equal(`${where}: ${E.shortText(play.cards)}`, actual, play);
    }
  }
  assert.ok(tractorViolations >= 50, `only ${tractorViolations} mustPlayTractor cases`);
  assert.ok(setViolations >= 50, `only ${setViolations} mustPlaySets or mustPlaySetTractor cases`);
  p.finish();
});

test("vectors: ruffed and over-ruffed tricks", () => {
  const p = parity("tricks");
  for (const [index, t] of edges.tricks.entries()) {
    const winners = t.plays.map((_, k) => E.winningIndex(t.plays.slice(0, k + 1), t.trump));
    p.equal(`trick ${index} ${t.plays.map((x) => E.shortText(x.cards)).join(" | ")}`, winners, t.winners);
  }
  p.finish();
});

// MARK: games.json

test("vectors: scoring table", () => {
  const p = parity("outcomes");
  for (const o of games.outcomes) {
    p.equal(`${o.points} points with ${o.decks ?? 2} decks`, E.scoreOutcome(o.points, o.decks ?? 2), o.outcome);
  }
  assert.ok(games.outcomes.filter((o) => o.decks === 4).length >= 100);
  p.finish();
});

test("vectors: game progression over many rounds", () => {
  const p = parity("games");
  let winners = 0;
  let bigGames = 0;
  for (const [index, g] of games.games.entries()) {
    if (g.players !== undefined) bigGames++;
    let game = E.newGame({ ...g.settings, table: tableOf(g) });
    for (const [step, s] of g.steps.entries()) {
      const where = `game ${index} (${E.rankLabel(g.settings.startRank)} to ${E.rankLabel(g.settings.targetRank)}), round ${step + 1}`;
      p.equal(`${where}: before`, { nextTrumpRank: E.nextTrumpRank(game), nextDealer: game.nextDealer },
        { nextTrumpRank: s.nextTrumpRank, nextDealer: s.nextDealer });
      const summary = E.recordRound(game, s.result);
      p.equal(`${where}: summary`, summary, { result: s.result, ...s.summary });
      p.equal(`${where}: state`, {
        levels: game.levels,
        nextDealer: game.nextDealer,
        roundsPlayed: game.roundsPlayed,
        winner: game.winner,
        nextTrumpRank: E.nextTrumpRank(game),
      }, s.state);
      // The explanation recomputed for seat 0 from the stored summary is the same text.
      p.equal(`${where}: summaryExplanation`, E.summaryExplanation(game, summary, 0), s.summary.explanation);
      game = JSON.parse(JSON.stringify(game)) as E.GameState;
    }
    p.equal(`game ${index}: history length`, game.history.length, g.steps.length);
    if (game.winner !== null) winners++;
  }
  assert.ok(games.games.length >= 20);
  assert.ok(winners >= 20, `only ${winners} games reached a winner`);
  assert.ok(bigGames >= 12, `only ${bigGames} games at bigger tables`);
  p.finish();
});

// MARK: views.json

/** JSON with null-valued object keys removed: Swift's Codable leaves nil optionals out. */
function withoutNulls(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(withoutNulls);
  if (value !== null && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, v] of Object.entries(value)) if (v !== null) out[key] = withoutNulls(v);
    return out;
  }
  return value;
}

test("vectors: seat views match the Swift SeatView JSON for every seat (4, 6 and 8 players)", () => {
  const p = parity("views");
  const labels = new Map<string, number>();
  const tables = new Map<number, number>();
  let summaries = 0;
  let winners = 0;
  for (const [index, c] of views.cases.entries()) {
    labels.set(c.label, (labels.get(c.label) ?? 0) + 1);
    const players = c.round.hands.length;
    tables.set(players, (tables.get(players) ?? 0) + 1);
    assert.equal(c.views.length, players);
    for (let seat = 0; seat < players; seat++) {
      // Round trip through JSON first: exactly what the server sends.
      const view = JSON.parse(JSON.stringify(E.toSeatView(c.game, c.round, seat, c.players))) as E.SeatView;
      if (view.lastRoundSummary !== null) summaries++;
      if (view.gameWinnerTeam !== null) winners++;
      p.equal(`case ${index} (${c.label}, round phase ${c.round.phase}), seat ${seat}`, withoutNulls(view),
        withoutNulls(c.views[seat]));
    }
  }
  assert.ok(views.cases.length >= 80, `only ${views.cases.length} view cases`);
  for (const label of ["burying", "buried", "playing", "finished", "recorded"]) {
    assert.ok((labels.get(label) ?? 0) >= 5, `only ${labels.get(label) ?? 0} ${label} cases`);
  }
  assert.ok(summaries >= 200 && winners >= 40, `summaries ${summaries}, winners ${winners}`);
  assert.ok((tables.get(6) ?? 0) >= 15 && (tables.get(8) ?? 0) >= 15, `cases per table size: ${JSON.stringify([...tables])}`);
  p.finish();
});
